export type Category = {
  id: CategoryId;
  name: string;
  blurb: string;
  image: string;
};

export type BoomCard = {
  id: string;
  category: CategoryId;
  word: string;
  before: string;
  after: string;
  distractors: [string, string, string];
  image: string;
  hint: string;
};

